-- PKG_DMF0020 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체
SELECT 'PKG_DMF0020' OBJ, 'PACKAGE' TYP, '10_SPEC.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0020' AND OBJECT_TYPE = 'PACKAGE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0020' AND OBJECT_TYPE = 'PACKAGE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 499915707741 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 494501673687 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0020' AND TYPE = 'PACKAGE' AND LINE > 1) H;
SELECT 'PKG_DMF0020' OBJ, 'PACKAGE BODY' TYP, '11_BODY.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0020' AND OBJECT_TYPE = 'PACKAGE BODY') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0020' AND OBJECT_TYPE = 'PACKAGE BODY') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 19497835517125 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 17572819270165 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0020' AND TYPE = 'PACKAGE BODY' AND LINE > 1) H;
