            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP' OBJ, 'PROCEDURE' TYP, '12_CALLER_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
