            WHEN H.S = 1505122455340 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 1503800460166 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
SELECT 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (1920881831651, 1920881831651) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

